import unittest
from candidate import incr_list

class TestIncrList(unittest.TestCase):
    def test_incr_list_normal(self):
        self.assertEqual(incr_list([1, 2, 3]), [2, 3, 4])

    def test_incr_list_empty(self):
        self.assertEqual(incr_list([]), [])

    def test_incr_list_single_element(self):
        self.assertEqual(incr_list([42]), [43])

    def test_incr_list_negative_numbers(self):
        self.assertEqual(incr_list([-1, -5, 0]), [0, -4, 1])

    def test_incr_list_floats(self):
        result = incr_list([1.5, 2.0, -3.2])
        self.assertAlmostEqual(result[0], 2.5)
        self.assertAlmostEqual(result[1], 3.0)
        self.assertAlmostEqual(result[2], -2.2)

    def test_incr_list_bool(self):
        self.assertEqual(incr_list([True, False]), [2, 1])

    def test_incr_list_tuple_input(self):
        self.assertEqual(incr_list((1, 2, 3)), [2, 3, 4])

    def test_incr_list_large_numbers(self):
        large = 10**100
        self.assertEqual(incr_list([large]), [large + 1])

    def test_incr_list_non_numeric_element_type_error(self):
        with self.assertRaises(TypeError):
            incr_list([1, "a", 3])

    def test_incr_list_none_input(self):
        with self.assertRaises(TypeError):
            incr_list(None)

    def test_incr_list_string_input(self):
        with self.assertRaises(TypeError):
            incr_list("123")

    def test_incr_list_dict_input(self):
        with self.assertRaises(TypeError):
            incr_list({"a": 1, "b": 2})

    def test_incr_list_original_list_unchanged(self):
        original = [1, 2, 3]
        _ = incr_list(original)
        self.assertEqual(original, [1, 2, 3])

    def test_incr_list_return_type_list(self):
        self.assertIsInstance(incr_list([1, 2]), list)

if __name__ == "__main__":
    unittest.main()
